function Header({ cart }) {
  const total = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div style={{
      background: "#ffd400",
      padding: "15px 20px",
      display: "flex",
      justifyContent: "space-between",
      fontWeight: "bold"
    }}>
      <div>📱 BAPhone</div>
      <div>🛒 Giỏ hàng ({total})</div>
    </div>
  );
}

export default Header;
